694: uint32_t  Path_ReadBinaryFile( const std::string &strFilename, unsigned char *pBuffer, uint32_t unSize )
695: {
696: 	FILE *f;
697: #if defined( POSIX )
698: 	f = fopen( strFilename.c_str(), "rb" );
699: #else
700: 	std::wstring wstrFilename = UTF8to16( strFilename.c_str() );
701: 	errno_t err = _wfopen_s( &f, wstrFilename.c_str(), L"rb" );
702: 	if ( err != 0 )
703: 	{
704: 		f = NULL;
705: 	}
706: #endif
707: 
708: 	uint32_t unSizeToReturn = 0;
709: 
710: 	if ( f != NULL )
711: 	{
712: 		fseek( f, 0, SEEK_END );
713: 		int nSize = ftell( f );
714: 		if ( nSize > 0 )
715: 		{
716: 			uint32_t size = (uint32_t) nSize;
717: 			fseek( f, 0, SEEK_SET );
718: 
719: 			if ( size > unSize || !pBuffer )
720: 			{
721: 				unSizeToReturn = size;
722: 			}
723: 			else
724: 			{
725: 				if ( fread( pBuffer, size, 1, f ) == 1 )
726: 				{
727: 					unSizeToReturn = size;
728: 				}
729: 			}
730: 		}
731: 
732: 		fclose( f );
733: 	}
734: 
735: 	return unSizeToReturn;
736: }
