741: #if defined( POSIX )
742: 	f = fopen(strFilename.c_str(), "wb");
743: #else
744: 	std::wstring wstrFilename = UTF8to16( strFilename.c_str() );
745: 	errno_t err = _wfopen_s( &f, wstrFilename.c_str(), L"wb" );
746: 	if (err != 0)
747: 	{
748: 		f = NULL;
749: 	}
750: #endif
