978: // -----------------------------------------------------------------------------------------------------
979: // Limits the set of characters that are allowed in filenames
980: // -----------------------------------------------------------------------------------------------------
981: std::string Path_SanitizeFilename( const std::string& sFilename )
982: {
983: 	std::string sFixed = sFilename;
984: 	std::string::iterator iLastDot = sFixed.end();
985: 	for ( std::string::iterator i = sFixed.begin(); i != sFixed.end(); i++ )
986: 	{
987: 		if ( *i == '.' )
988: 		{
989: 			iLastDot = i;
990: 		}
991: 
992: 		// path-related characters are forbidden (except the last period)
993: 		switch ( *i )
994: 		{
995: 			case '\0':
996: 			case '.':
997: 			case '\\':
998: 			case '/':
999: 			case ':':
1000: 			case '|':
