/** Returns the path (including filename) to the current executable */
std::string Path_GetExecutablePath()
{
#if defined( _WIN32 )
	wchar_t *pwchPath = new wchar_t[MAX_UNICODE_PATH];
	char *pchPath = new char[MAX_UNICODE_PATH_IN_UTF8];
	::GetModuleFileNameW( NULL, pwchPath, MAX_UNICODE_PATH );
	WideCharToMultiByte( CP_UTF8, 0, pwchPath, -1, pchPath, MAX_UNICODE_PATH_IN_UTF8, NULL, NULL );
	delete[] pwchPath;

	std::string sPath = pchPath;
	delete[] pchPath;
	return sPath;
#elif defined( OSX )
	char rchPath[1024];
	uint32_t nBuff = sizeof( rchPath );
	bool bSuccess = _NSGetExecutablePath(rchPath, &nBuff) == 0;
	rchPath[nBuff-1] = '\0';
	if( bSuccess )
		return rchPath;
	else
		return "";
#elif defined LINUX
	char rchPath[1024];
	size_t nBuff = sizeof( rchPath );
	ssize_t nRead = readlink("/proc/self/exe", rchPath, nBuff-1 );
	if ( nRead != -1 )
	{
		rchPath[ nRead ] = 0;
		return rchPath;
	}
	else
	{
		return "";
	}
#else
	AssertMsg( false, "Implement Plat_GetExecutablePath" );
	return "";
#endif

}

/** Returns the filename (excluding directory and extension) of the current executable */
std::string Path_GetExecutableName()
{
	std::string sExeFilename = Path_StripExtension( Path_StripDirectory( Path_GetExecutablePath() ) );
#if defined( ANDROID )
	// We determine the App ID by looking at `/proc/self/cmdline`, as Zygote changes our process name to match.
	FILE *pCmdlineFile = fopen( "/proc/self/cmdline", "r" );
	if ( pCmdlineFile != NULL )
	{
		// Google Play says the maximum allowable length is 150 characters
		char rgchAndroidAppID[ 151 ] = { 0 };
		fgets( rgchAndroidAppID, sizeof( rgchAndroidAppID ), pCmdlineFile );
		fclose( pCmdlineFile );
		if ( rgchAndroidAppID[ 0 ] != '\0' )
		{
			sExeFilename = rgchAndroidAppID;
		}
	}
#endif
	return sExeFilename;
}

/** Returns the path of the current working directory */
std::string Path_GetWorkingDirectory()
{
	std::string sPath;
#if defined( _WIN32 )
	wchar_t buf[MAX_UNICODE_PATH];
	sPath = UTF16to8( _wgetcwd( buf, MAX_UNICODE_PATH ) );
#else
	char buf[ 1024 ];
	sPath = getcwd( buf, sizeof( buf ) );
#endif
	return sPath;
}

/** Sets the path of the current working directory. Returns true if this was successful. */
bool Path_SetWorkingDirectory( const std::string & sPath )
{
	bool bSuccess;
#if defined( _WIN32 )
	std::wstring wsPath = UTF8to16( sPath.c_str() );
	bSuccess = 0 == _wchdir( wsPath.c_str() );
#else
	bSuccess = 0 == chdir( sPath.c_str() );
#endif
	return bSuccess;
}

/** Gets the path to a temporary directory. */
std::string Path_GetTemporaryDirectory()
{
