			vecFileContents.resize( size );
			if ( fread( &vecFileContents[ 0 ], size, 1, f ) == 1 )
			{
			}
			else
			{
				vecFileContents.clear();
			}
		}

		fclose( f );
	}

	return vecFileContents ;
}


