172: 	pvecHistory->reserve( arrayNode.size() );
173: 	for( uint32_t unIndex = 0; unIndex < arrayNode.size(); unIndex++ )
174: 	{
175: 		std::string sPath( arrayNode[ unIndex ].asString() );
176: 		pvecHistory->push_back( sPath );
