458: static int FileSelect( const char *name, const char *mask )
459: {
460: 	// printf("Test:%s %s\n",mask,name);
461: 
462: 	if ( !strcmp( name, "." ) || !strcmp( name, ".." ) )
463: 		return 0;
464: 
465: 	if ( !strcmp( mask, "*.*" ) || !strcmp( mask, "*" ) )
466: 		return 1;
467: 
468: 	while ( *mask && *name )
469: 	{
470: 		if ( *mask == '*' )
471: 		{
472: 			mask++;		  // move to the next char in the mask
473: 			if ( !*mask ) // if this is the end of the mask its a match
474: 			{
475: 				return 1;
476: 			}
477: 			while ( *name && toupper( *name ) != toupper( *mask ) )
478: 			{ // while the two don't meet up again
479: 				name++;
480: 			}
481: 			if ( !*name )
482: 			{ // end of the name
483: 				break;
484: 			}
485: 		}
486: 		else if ( *mask != '?' )
487: 		{
488: 			if ( toupper( *mask ) != toupper( *name ) )
489: 			{ // mismatched!
490: 				return 0;
491: 			}
492: 			else
493: 			{
494: 				mask++;
495: 				name++;
496: 				if ( !*mask && !*name )
497: 				{ // if its at the end of the buffer
498: 					return 1;
499: 				}
500: 			}
501: 		}
502: 		else /* mask is "?", we don't care*/
503: 		{
504: 			mask++;
505: 			name++;
506: 		}
507: 	}
508: 
509: 	return ( !*mask && !*name ); // both of the strings are at the end
510: }
