CDirIterator::CDirIterator( const char *pchPath, const char *pchPattern )
{
	m_pFindData = NULL;

	// put in the path
	if ( pchPath )
	{
		std::string sPathAndPattern = Path_Join( pchPath, pchPattern );

		Init( sPathAndPattern.c_str() );
	}
	else
