164: 
165: 	va_list args;
166: 	char pchBuffer[k_ulMaxStackString];
167: 
168: 	va_start( args, pchFormat );
169: 	int unSize = vsnprintf( pchBuffer, sizeof( pchBuffer ), pchFormat, args );
170: 	va_end( args );
171: 
172: 	// Something went fairly wrong
173: 	if ( unSize < 0 )
174: 	{
175: 		AssertMsg( false, "Format string parse failure" );
176: 		return "";
177: 	}
178: 
179: 	// Processing on the stack worked, success
180: 	if ( unSize < k_ulMaxStackString )
181: 	{
182: 		return pchBuffer;
183: 	}
184: 
185: 	// If processing on the stack failed, fallback to a dynamic allocation
186: 	std::vector< char > vecChar{};
187: 	vecChar.resize( unSize + 1 );
188: 
189: 	va_start( args, pchFormat );
190: 	unSize = vsnprintf( vecChar.data(), vecChar.size(), pchFormat, args );
191: 	va_end( args );
192: 
193: 	// Double check, just in case
194: 	if ( unSize < 0 )
195: 	{
196: 		AssertMsg( false, "Format string parse failure" );
197: 		return "";
198: 	}
199: 
200: 	return vecChar.data();
201: }
