532: void V_StripExtension( std::string &in )
533: {
534: 	// Find the last dot. If it's followed by a dot or a slash, then it's part of a 
535: 	// directory specifier like ../../somedir/./blah.
536: 	std::string::size_type test = in.rfind( '.' );
537: 	if ( test != std::string::npos )
538: 	{
539: 		// This handles things like ".\blah" or "c:\my@email.com\abc\def\geh"
540: 		// Which would otherwise wind up with "" and "c:\my@email", respectively.
541: 		if ( in.rfind( '\\' ) < test && in.rfind( '/' ) < test )
542: 		{
543: 			in.resize( test );
544: 		}
