570: //-----------------------------------------------------------------------------
571: // Purpose: Repairs a should-be-UTF-8 string to a for-sure-is-UTF-8 string, plus return boolean if we subbed in '?' somewhere
572: //-----------------------------------------------------------------------------
573: bool RepairUTF8( const char *pbegin, const char *pend, std::string & sOutputUtf8 )
574: {
575: 	typedef std::codecvt_utf8<char32_t> facet_type;
576: 	facet_type myfacet;
577: 
578: 	std::mbstate_t mystate = std::mbstate_t();
579: 
580: 	sOutputUtf8.clear();
581: 	sOutputUtf8.reserve( pend - pbegin );
582: 	bool bSqueakyClean = true;
583: 
584: 	const char *pmid = pbegin;
585: 	while ( pmid != pend )
586: 	{
587: 		bool bHasError = false;
588: 		bool bHasValidData = false;
589: 
590: 		char32_t out = 0xdeadbeef, *pout;
591: 		pbegin = pmid;
592: 		switch ( myfacet.in( mystate, pbegin, pend, pmid, &out, &out + 1, pout ) )
593: 		{
594: 		case facet_type::ok:
595: 			bHasValidData = true;
596: 			break;
597: 
598: 		case facet_type::noconv:
599: 			// unexpected! always converting type
600: 			bSqueakyClean = false;
601: 			break;
602: 
603: 		case facet_type::partial:
604: 			bHasError = pbegin == pmid;
605: 			if ( bHasError )
606: 			{
607: 				bSqueakyClean = false;
608: 			}
609: 			else
610: 			{
611: 				bHasValidData = true;
612: 			}
613: 			break;
614: 
615: 		case facet_type::error:
616: 			bHasError = true;
617: 			bSqueakyClean = false;
618: 			break;
619: 		}
620: 
621: 		if ( bHasValidData )
622: 		{
623: 			// could convert back, but no need
624: 			for ( const char *p = pbegin; p != pmid; ++p )
625: 			{
626: 				sOutputUtf8 += *p;
627: 			}
628: 		}
629: 
630: 		if ( bHasError )
631: 		{
632: 			sOutputUtf8 += '?';
633: 		}
634: 
635: 		if ( pmid == pbegin )
636: 		{
637: 			pmid++;
638: 		}
639: 	}
640: 
641: 	return bSqueakyClean;
642: }
